import math

def get_divisors(n):
    divs = set()
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            divs.add(i)
            divs.add(n // i)
    return sorted(list(divs))

def check_condition(n, divisors):
    # Need at least 5 divisors
    if len(divisors) < 5:
        return False

    # Divisors are 1-indexed: d1=1, d2=a, d3=b, d4, d5=c
    a = divisors[1]
    b = divisors[2]
    c = divisors[4]

    # Check the derived condition: n = ab + ac + bc
    target_n = a * b + a * c + b * c
    return target_n == n

# Store results
possible_tau = set()
examples_tau = {}

# Sweep up to 1000
for n in range(1, 1001):
    divisors = get_divisors(n)
    tau_n = len(divisors)

    if tau_n >= 5:
        if check_condition(n, divisors):
            possible_tau.add(tau_n)
            if tau_n not in examples_tau:
                examples_tau[tau_n] = []
            examples_tau[tau_n].append(n)

# Output results in a readable format
print(f"--- Results up to N=1000 ---")
print(f"Possible values for tau(n): {sorted(list(possible_tau))}")
print("\nExamples found:")
for tau, examples in examples_tau.items():
    print(f"Tau(n) = {tau}: Examples = {examples}")

